rocq.statement:
Lemma ker_add `{VS1 : VSpace} `{VS2 : VSpace}
  (L : Lin) (x y : V0) :
  ker L x -> ker L y -> ker L (x +V y).

Lemma im_add `{VS1 : VSpace} `{VS2 : VSpace}
  (L : Lin) (y z : V0) :
  im L y -> im L z -> im L (y +V z).

Lemma im_smul `{VS1 : VSpace} `{VS2 : VSpace}
  (L : Lin) (a : R0) (y : V0) :
  im L y -> im L (a •V y).

lean4.proof:
intro Heq
constructor
· intro i j; have := Heq i j; simpa [this]
  using (Preorder.refl (B i j))
· intro i j; have := Heq i j; simpa [this]
  using (Preorder.refl (A i j))
